<?php session_start(); require __DIR__.'/../includes/db.php'; $error=''; if(isset($_SESSION['admin_id'])){header('Location: dashboard.php');exit;} if($_SERVER['REQUEST_METHOD']==='POST'){ $email=trim($_POST['email']??'');$password=$_POST['password']??'';$st=mysqli_prepare($conn,"SELECT id,name,password FROM admins WHERE email=? LIMIT 1");mysqli_stmt_bind_param($st,'s',$email);mysqli_stmt_execute($st);$a=mysqli_fetch_assoc(mysqli_stmt_get_result($st));if($a&&password_verify($password,$a['password'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$a['name'];header('Location: dashboard.php');exit;} $error='Invalid admin login.';} ?><!DOCTYPE html><html><head><meta charset="UTF-8"><title>Admin Login | ClassyCubic</title><link rel="stylesheet" href="../css/style.css"></head><body><div class="form-card"><h2>ClassyCubic Admin</h2><?php if($error): ?><div class="alert-box error"><?php echo htmlspecialchars($error); ?></div><?php endif; ?><form method="POST"><label>Email</label><input type="email" name="email" required><label>Password</label><input type="password" name="password" required><button>Login</button></form><p style="margin-top:15px">Default: admin@classycubic.com / Admin@12345</p></div></body></html>